INSERT INTO categories (slug, name, description, icon, position) VALUES ('web', 'Web & networking', 'HTTP, sockets and web frameworks.', '↗', 1);
INSERT INTO categories (slug, name, description, icon, position) VALUES ('data', 'Data & serialization', 'Read, write and exchange structured data.', '{}', 2);
INSERT INTO categories (slug, name, description, icon, position) VALUES ('text', 'Text & markup', 'Templates, formatting and safe HTML.', 'Aa', 3);
INSERT INTO categories (slug, name, description, icon, position) VALUES ('system', 'System & tooling', 'Files, processes and command-line tools.', '>_', 4);
INSERT INTO categories (slug, name, description, icon, position) VALUES ('utilities', 'Utilities', 'Time, identifiers and everyday building blocks.', '◷', 5);
INSERT INTO categories (slug, name, description, icon, position) VALUES ('other', 'Other', 'Modules that fit no other category yet.', '…', 6);
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('http', 'HTTP', 'web', 'An HTTP/1.1 client and fiber-based server built on iyi sockets.', 'https://github.com/iyilang/iyi/blob/master/src/std/http.iyi', 'import std/http::{Server, Response}', 'HTTP only; no TLS in the native client.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('socket', 'Sockets', 'web', 'TCP and Unix sockets with cooperative, cancellable I/O.', 'https://github.com/iyilang/iyi/blob/master/src/std/socket.iyi', 'import std/socket::{IyiSocket}', 'Native runtime socket support.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('json', 'JSON', 'data', 'Parse and generate JSON with typed values and streaming APIs.', 'https://github.com/iyilang/iyi/blob/master/src/std/json.iyi', 'import std/json::{JSON}', 'Parser, builder and serialization helpers.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('yaml', 'YAML', 'data', 'Read and write YAML configuration and structured documents.', 'https://github.com/iyilang/iyi/blob/master/src/std/yaml.iyi', 'import std/yaml::{YAML}', 'Check the module interface for supported YAML features.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('csv', 'CSV', 'data', 'Read and write comma-separated tabular data.', 'https://github.com/iyilang/iyi/blob/master/src/std/csv.iyi', 'import std/csv::{CSV}', 'Useful for imports, exports and small data pipelines.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('uri', 'URI', 'web', 'Parse URLs, encode path segments and handle query parameters.', 'https://github.com/iyilang/iyi/blob/master/src/std/uri.iyi', 'import std/uri::{URI, Params}', 'Includes form encoding and query parsing.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('html', 'HTML', 'text', 'Escape HTML safely and decode character entities.', 'https://github.com/iyilang/iyi/blob/master/src/std/html.iyi', 'import std/html::{HTML}', 'Escape dynamic content before rendering HTML.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('text', 'Text', 'text', 'String helpers for splitting, replacement and text processing.', 'https://github.com/iyilang/iyi/blob/master/src/std/text.iyi', 'import std/text::*', 'Extends the small native string surface.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('format', 'Formatting', 'text', 'Format numbers and values for readable output.', 'https://github.com/iyilang/iyi/blob/master/src/std/format.iyi', 'import std/format::*', 'Formatting lives outside the minimal prelude.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('file', 'Files', 'system', 'File operations beyond whole-file reads and writes.', 'https://github.com/iyilang/iyi/blob/master/src/std/file.iyi', 'import std/file::*', 'Basic File.read and File.write are also in the prelude.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('process', 'Processes', 'system', 'Launch processes and work with subprocess output.', 'https://github.com/iyilang/iyi/blob/master/src/std/process.iyi', 'import std/process::*', 'Operating-system and target support varies.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('option_parser', 'CLI options', 'system', 'Turn command-line flags into a clear command-line interface.', 'https://github.com/iyilang/iyi/blob/master/src/std/option_parser.iyi', 'import std/option_parser::*', 'A standard module for command-line tools.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('time', 'Time', 'utilities', 'Dates, durations and time-related operations.', 'https://github.com/iyilang/iyi/blob/master/src/std/time.iyi', 'import std/time::*', 'Consult the module interface for available operations.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('uuid', 'UUID', 'utilities', 'Generate and work with universally unique identifiers.', 'https://github.com/iyilang/iyi/blob/master/src/std/uuid.iyi', 'import std/uuid::*', 'Standard identifier utilities.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('base64', 'Base64', 'data', 'Encode and decode binary data as Base64 text.', 'https://github.com/iyilang/iyi/blob/master/src/std/base64.iyi', 'import std/base64::*', 'Encoding is not encryption.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('log', 'Logging', 'system', 'Structured application logging and diagnostics.', 'https://github.com/iyilang/iyi/blob/master/src/std/log.iyi', 'import std/log::*', 'Standard logging utilities.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('udp', 'UDP', 'web', 'Datagram sockets with IPv4, IPv6 and localhost addresses.', 'https://github.com/iyilang/iyi/blob/master/src/std/udp.iyi', 'import std/udp::{UdpSocket, Datagram}', 'Numeric addresses only; no DNS lookup.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('hpack', 'HPACK', 'web', 'HTTP/2 header compression: static and dynamic tables and Huffman coding (RFC 7541).', 'https://github.com/iyilang/iyi/blob/master/src/std/hpack.iyi', 'import std/hpack::*', 'A building block for HTTP/2, not a client or server.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('capsule', 'Capsule', 'web', 'HTTP Datagrams and the Capsule Protocol (RFC 9297), with QUIC variable-length integers.', 'https://github.com/iyilang/iyi/blob/master/src/std/capsule.iyi', 'import std/capsule::*', 'A building block for HTTP/3 and extended CONNECT.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('xml', 'XML', 'data', 'A well-formedness parser, a document tree and a serializer for XML 1.0.', 'https://github.com/iyilang/iyi/blob/master/src/std/xml.iyi', 'import std/xml::{Document, Node}', 'Checks well-formedness; no schema validation.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('ini', 'INI', 'data', 'Read INI configuration: sections, key = value lines and comments.', 'https://github.com/iyilang/iyi/blob/master/src/std/ini.iyi', 'import std/ini::{INI}', 'Refuses malformed lines with their line number.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('compress', 'Compress', 'data', 'DEFLATE, zlib and gzip, written in iyi.', 'https://github.com/iyilang/iyi/blob/master/src/std/compress.iyi', 'import std/compress::{Deflate, Zlib, Gzip}', 'No zlib is linked.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('digest', 'Digest', 'utilities', 'MD5, SHA-1, SHA-256, CRC-32 and Adler-32 checksums.', 'https://github.com/iyilang/iyi/blob/master/src/std/digest.iyi', 'import std/digest::{SHA256, MD5, CRC32}', 'No OpenSSL. MD5 and SHA-1 are checksums, not security.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('regex', 'Regex', 'text', 'Regular expressions in linear time, with RE2''s guarantees.', 'https://github.com/iyilang/iyi/blob/master/src/std/regex.iyi', 'import std/regex::{Regex}', 'No lookaround or backreferences, so no catastrophic backtracking.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('eiy', 'Eiy', 'text', 'Embedded iyi templates, <%= %> style, compiled into the program.', 'https://github.com/iyilang/iyi/blob/master/src/std/eiy.iyi', 'import std/eiy::{Eiy}', 'Templates become code at compile time.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('unicode', 'Unicode', 'text', 'Unicode character data: categories, case mapping, UTF-8 and UTF-16, normalization.', 'https://github.com/iyilang/iyi/blob/master/src/std/unicode.iyi', 'import std/unicode::{Unicode}', 'Tables generated from the Unicode Character Database.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('levenshtein', 'Levenshtein', 'text', 'Edit distance and fuzzy string matching.', 'https://github.com/iyilang/iyi/blob/master/src/std/levenshtein.iyi', 'import std/levenshtein::*', 'Levenshtein and optimal string alignment distances.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('colorize', 'Colorize', 'system', 'Terminal colours and styles with ANSI escapes: named, 256-colour and RGB.', 'https://github.com/iyilang/iyi/blob/master/src/std/colorize.iyi', 'import std/colorize::*', 'Adds colorize to String.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('dir', 'Dir', 'system', 'Read, create, delete and walk directories, and glob for files.', 'https://github.com/iyilang/iyi/blob/master/src/std/dir.iyi', 'import std/dir::{Dir}', 'No external C libraries.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('env', 'ENV', 'system', 'Read and change the process environment.', 'https://github.com/iyilang/iyi/blob/master/src/std/env.iyi', 'import std/env::{ENV}', 'A hash-like view of environment variables.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('path', 'Path', 'system', 'File system paths for POSIX and Windows, read without touching the disk.', 'https://github.com/iyilang/iyi/blob/master/src/std/path.iyi', 'import std/path::{Path}', 'Lexical only: nothing here reads the file system.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('signal', 'Signal', 'system', 'Wait for signals such as INT and TERM to stop a program cleanly.', 'https://github.com/iyilang/iyi/blob/master/src/std/signal.iyi', 'import std/signal::{Signal}', 'A signal is a value a task waits for.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('io', 'IO', 'system', 'Byte streams beyond the standard ones: memory buffers, limited and delimited readers, tees.', 'https://github.com/iyilang/iyi/blob/master/src/std/io.iyi', 'import std/io::{Memory}', 'Extends the prelude''s IyiIO.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('benchmark', 'Benchmark', 'system', 'Time a block: iterations per second and wall-clock comparisons.', 'https://github.com/iyilang/iyi/blob/master/src/std/benchmark.iyi', 'import std/benchmark::{Benchmark}', 'Wall-clock time only.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('big', 'Big numbers', 'utilities', 'Arbitrary precision BigInt, BigDecimal and BigRational.', 'https://github.com/iyilang/iyi/blob/master/src/std/big.iyi', 'import std/big::{BigInt, BigDecimal, BigRational}', 'Written in iyi; no GMP.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('complex', 'Complex', 'utilities', 'Complex numbers with exponentials, logarithms and roots.', 'https://github.com/iyilang/iyi/blob/master/src/std/complex.iyi', 'import std/complex::{Complex}', 'Built on std/math.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('math', 'Math', 'utilities', 'Trigonometry, logarithms, roots and other numeric functions.', 'https://github.com/iyilang/iyi/blob/master/src/std/math.iyi', 'import std/math::{Math}', 'Float32 and Float64 overloads.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('random', 'Random', 'utilities', 'A seedable PCG-32 random number generator.', 'https://github.com/iyilang/iyi/blob/master/src/std/random.iyi', 'import std/random::{Random}', 'The same stream as Crystal''s Random for a given seed.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('semantic_version', 'SemanticVersion', 'utilities', 'Parse and compare Semantic Versioning 2.0.0 versions.', 'https://github.com/iyilang/iyi/blob/master/src/std/semantic_version.iyi', 'import std/semantic_version::{SemanticVersion}', 'Refuses anything the grammar does not allow.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('deque', 'Deque', 'utilities', 'A double-ended queue over a ring buffer.', 'https://github.com/iyilang/iyi/blob/master/src/std/deque.iyi', 'import std/deque::{Deque}', 'Amortised O(1) at both ends.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('heap', 'Heap', 'utilities', 'A binary min-heap over Comparable values.', 'https://github.com/iyilang/iyi/blob/master/src/std/heap.iyi', 'import std/heap::{Heap}', 'Smallest element first.', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('set', 'Set', 'utilities', 'Set algebra for the built-in Set: union, intersection, difference, subsets.', 'https://github.com/iyilang/iyi/blob/master/src/std/set.iyi', 'import std/set', 'Reopens the prelude''s Set(T).', 'Apache-2.0', 'Standard library');
INSERT INTO packages (slug, name, category, description, source, usage, note, license, distribution) VALUES ('bit_array', 'BitArray', 'utilities', 'A compact array of booleans, stored as bits.', 'https://github.com/iyilang/iyi/blob/master/src/std/bit_array.iyi', 'import std/bit_array::{BitArray}', 'Packed into 64-bit words.', 'Apache-2.0', 'Standard library');
